-- ganesha_standard #3.instruction_ta
update public.pooja_steps set instruction_ta = replace(instruction_ta, 'இரு கைகளின் நெரிக்கும் விரல் மூட்டுகளால் நெற்றிப் பொட்டுகளில் மெதுவாகத் தட்டியபடி பாராயணம் செய்யவும்.', 'இரு கைகளையும் லேசாக மடக்கி, விரல் முட்டிகளால் இரு நெற்றிப் பொட்டுகளிலும் மெதுவாக ஐந்து முறை குட்டியபடி சொல்லவும்.'), updated_at = now()
 where pooja_id = 'ganesha_standard' and step_number = 3 and step_title_en = 'Vighneshwara Dhyanam' and position('இரு கைகளின் நெரிக்கும் விரல் மூட்டுகளால் நெற்றிப் பொட்டுகளில் மெதுவாகத் தட்டியபடி பாராயணம் செய்யவும்.' in instruction_ta) > 0 and position('இரு கைகளையும் லேசாக மடக்கி, விரல் முட்டிகளால் இரு நெற்றிப் பொட்டுகளிலும் மெதுவாக ஐந்து முறை குட்டியபடி சொல்லவும்.' in instruction_ta) = 0;

