-- ganesha_standard #4.instruction_en
update public.pooja_steps set instruction_en = replace(instruction_en, 'Close the right nostril with the thumb, inhale through the left. Close both, hold breath and mentally chant the mantra. Exhale through the right.', 'With the right hand, fold the index and middle fingers into the palm. The mantra has three parts and the breath is assigned to each. Close the right nostril with the thumb and breathe IN through the left nostril, reciting silently from om bhuh to om satyam. Close the left nostril too, with the ring and little fingers, and HOLD the breath through om tat savitur to prachodayat. Open the right nostril and breathe OUT through it, through om aapo jyoti to bhurbhuvassuvarom. Then touch the right ear with the right hand.'), updated_at = now()
 where pooja_id = 'ganesha_standard' and step_number = 4 and step_title_en = 'Pranayamam' and position('Close the right nostril with the thumb, inhale through the left. Close both, hold breath and mentally chant the mantra. Exhale through the right.' in instruction_en) > 0 and position('With the right hand, fold the index and middle fingers into the palm. The mantra has three parts and the breath is assigned to each. Close the right nostril with the thumb and breathe IN through the left nostril, reciting silently from om bhuh to om satyam. Close the left nostril too, with the ring and little fingers, and HOLD the breath through om tat savitur to prachodayat. Open the right nostril and breathe OUT through it, through om aapo jyoti to bhurbhuvassuvarom. Then touch the right ear with the right hand.' in instruction_en) = 0;

