update public.pooja_steps set instruction_ta = replace(instruction_ta, 'கட்டைவிரலால் வலது நாசியை மூடி, இடது நாசி வழியாக மூச்சை உள்ளிழுக்கவும். இரு நாசிகளையும் மூடி மூச்சை நிறுத்தி, மனதிற்குள் மந்திரத்தைச் சொல்லவும். பின் வலது நாசி வழியாக மெல்ல வெளியிடவும்.', 'வலது கையில் ஆள்காட்டி விரலையும் நடுவிரலையும் உள்ளங்கையில் மடக்கவும். மந்திரம் மூன்று பகுதிகள்; ஒவ்வொன்றுக்கும் மூச்சின் ஒரு நிலை. கட்டைவிரலால் வலது நாசியை மூடி, "ஓம் பூ" முதல் "ஓம் ஸத்யம்" வரை மனதிற்குள் சொல்லியபடி இடது நாசி வழியாக மூச்சை இழுக்கவும். மோதிர விரல், சுண்டு விரல்களால் இடது நாசியையும் மூடி, "ஓம் தத் ஸவிது" முதல் "ப்ரசோதயாத்" வரை சொல்லியபடி மூச்சை நிறுத்தவும். பின் வலது நாசியைத் திறந்து, "ஓமாபோ ஜ்யோதீ" முதல் "பூர்புவஸ்ஸுவரோம்" வரை சொல்லியபடி அதன் வழியாக மூச்சை வெளியிடவும். இறுதியில் வலது கையால் வலது காதைத் தொடவும்.'), updated_at = now()
 where pooja_id = 'ganesha_standard' and step_number = 4 and step_title_en = 'Pranayamam' and position('கட்டைவிரலால் வலது நாசியை மூடி, இடது நாசி வழியாக மூச்சை உள்ளிழுக்கவும். இரு நாசிகளையும் மூடி மூச்சை நிறுத்தி, மனதிற்குள் மந்திரத்தைச் சொல்லவும். பின் வலது நாசி வழியாக மெல்ல வெளியிடவும்.' in instruction_ta) > 0 and position('வலது கையில் ஆள்காட்டி விரலையும் நடுவிரலையும் உள்ளங்கையில் மடக்கவும். மந்திரம் மூன்று பகுதிகள்; ஒவ்வொன்றுக்கும் மூச்சின் ஒரு நிலை. கட்டைவிரலால் வலது நாசியை மூடி, "ஓம் பூ" முதல் "ஓம் ஸத்யம்" வரை மனதிற்குள் சொல்லியபடி இடது நாசி வழியாக மூச்சை இழுக்கவும். மோதிர விரல், சுண்டு விரல்களால் இடது நாசியையும் மூடி, "ஓம் தத் ஸவிது" முதல் "ப்ரசோதயாத்" வரை சொல்லியபடி மூச்சை நிறுத்தவும். பின் வலது நாசியைத் திறந்து, "ஓமாபோ ஜ்யோதீ" முதல் "பூர்புவஸ்ஸுவரோம்" வரை சொல்லியபடி அதன் வழியாக மூச்சை வெளியிடவும். இறுதியில் வலது கையால் வலது காதைத் தொடவும்.' in instruction_ta) = 0;

