-- ganesha_standard #13.instruction_en
update public.pooja_steps set instruction_en = replace(instruction_en, 'Then Place a few grains of akshatai and a drop of water in your right palm. Close it with your left hand and place it on your right thigh.', 'Then put a few grains of akshatai and a drop of water in your left palm and rest it, palm up, on your right thigh. Cover it with your right palm, crossed over the left, and keep both hands there while you recite. At the end, wash your hands.'), updated_at = now()
 where pooja_id = 'ganesha_standard' and step_number = 13 and step_title_en = 'Sankalpam' and position('Then Place a few grains of akshatai and a drop of water in your right palm. Close it with your left hand and place it on your right thigh.' in instruction_en) > 0 and position('Then put a few grains of akshatai and a drop of water in your left palm and rest it, palm up, on your right thigh. Cover it with your right palm, crossed over the left, and keep both hands there while you recite. At the end, wash your hands.' in instruction_en) = 0;

-- ganesha_standard #13.instruction_ta
update public.pooja_steps set instruction_ta = replace(instruction_ta, 'வலது உள்ளங்கையில் சிறிது அட்சதையும் ஒரு துளி நீரும் வைத்து, இடது கையால் மூடி, வலது தொடையின் மீது வைத்துக் கொள்ளவும்.', 'இதற்கு முன், சிறிது அக்ஷதையைக் கையில் வைத்துக்கொண்டு மீண்டும் ஒரு முறை ப்ராணாயாமம் செய்து, வலது கையால் வலது காதைத் தொடவும். பின் இடது உள்ளங்கையில் சிறிது அக்ஷதையும் ஒரு துளி நீரும் வைத்து, அதை மேல்நோக்கியபடி வலது தொடையின் மேல் வைக்கவும். வலது உள்ளங்கையை அதன் மேல் குறுக்காக வைத்து மூடி, சொல்லி முடியும் வரை அப்படியே வைத்திருக்கவும். முடிவில் கைகளைக் கழுவவும்.'), updated_at = now()
 where pooja_id = 'ganesha_standard' and step_number = 13 and step_title_en = 'Sankalpam' and position('வலது உள்ளங்கையில் சிறிது அட்சதையும் ஒரு துளி நீரும் வைத்து, இடது கையால் மூடி, வலது தொடையின் மீது வைத்துக் கொள்ளவும்.' in instruction_ta) > 0 and position('இதற்கு முன், சிறிது அக்ஷதையைக் கையில் வைத்துக்கொண்டு மீண்டும் ஒரு முறை ப்ராணாயாமம் செய்து, வலது கையால் வலது காதைத் தொடவும். பின் இடது உள்ளங்கையில் சிறிது அக்ஷதையும் ஒரு துளி நீரும் வைத்து, அதை மேல்நோக்கியபடி வலது தொடையின் மேல் வைக்கவும். வலது உள்ளங்கையை அதன் மேல் குறுக்காக வைத்து மூடி, சொல்லி முடியும் வரை அப்படியே வைத்திருக்கவும். முடிவில் கைகளைக் கழுவவும்.' in instruction_ta) = 0;

