-- saraswati_pooja #6.instruction_en
update public.pooja_steps set instruction_en = replace(instruction_en, 'Take akshatai and a flower in the right hand, cover it with the left and rest both on the right thigh. Recite the day and place and the resolve to worship Saraswati. Place the akshatai to the north and wash the hand.', 'Put akshatai and a flower in your left palm and rest it, palm up, on your right thigh. Cover it with your right palm, crossed over the left, and keep both hands there while you recite the day and place and the resolve to worship Saraswati. Place the akshatai to the north and wash your hands.'), updated_at = now()
 where pooja_id = 'saraswati_pooja' and step_number = 6 and step_title_en = 'Sankalpam' and position('Take akshatai and a flower in the right hand, cover it with the left and rest both on the right thigh. Recite the day and place and the resolve to worship Saraswati. Place the akshatai to the north and wash the hand.' in instruction_en) > 0 and position('Put akshatai and a flower in your left palm and rest it, palm up, on your right thigh. Cover it with your right palm, crossed over the left, and keep both hands there while you recite the day and place and the resolve to worship Saraswati. Place the akshatai to the north and wash your hands.' in instruction_en) = 0;

-- saraswati_pooja #6.instruction_ta
update public.pooja_steps set instruction_ta = replace(instruction_ta, 'வலது கையில் அக்ஷதையும் புஷ்பமும் எடுத்து இடது கையால் மூடி வலது தொடையின் மேல் வைக்கவும். நாள், இடம், ஸரஸ்வதீ பூஜை செய்வதாக ஸங்கல்பம் சொல்லவும். அக்ஷதையை வடக்குப் பக்கம் போட்டுக் கையைக் கழுவவும்.', 'இடது உள்ளங்கையில் அக்ஷதையும் புஷ்பமும் வைத்து, அதை மேல்நோக்கியபடி வலது தொடையின் மேல் வைக்கவும். வலது உள்ளங்கையை அதன் மேல் குறுக்காக வைத்து மூடி, அப்படியே வைத்தபடி நாள், இடம், ஸரஸ்வதீ பூஜை செய்வதாக ஸங்கல்பம் சொல்லவும். அக்ஷதையை வடக்குப் பக்கம் போட்டுக் கைகளைக் கழுவவும்.'), updated_at = now()
 where pooja_id = 'saraswati_pooja' and step_number = 6 and step_title_en = 'Sankalpam' and position('வலது கையில் அக்ஷதையும் புஷ்பமும் எடுத்து இடது கையால் மூடி வலது தொடையின் மேல் வைக்கவும். நாள், இடம், ஸரஸ்வதீ பூஜை செய்வதாக ஸங்கல்பம் சொல்லவும். அக்ஷதையை வடக்குப் பக்கம் போட்டுக் கையைக் கழுவவும்.' in instruction_ta) > 0 and position('இடது உள்ளங்கையில் அக்ஷதையும் புஷ்பமும் வைத்து, அதை மேல்நோக்கியபடி வலது தொடையின் மேல் வைக்கவும். வலது உள்ளங்கையை அதன் மேல் குறுக்காக வைத்து மூடி, அப்படியே வைத்தபடி நாள், இடம், ஸரஸ்வதீ பூஜை செய்வதாக ஸங்கல்பம் சொல்லவும். அக்ஷதையை வடக்குப் பக்கம் போட்டுக் கைகளைக் கழுவவும்.' in instruction_ta) = 0;

-- nitya_panchayatana #5.instruction_en
update public.pooja_steps set instruction_en = replace(instruction_en, 'Hold akshatai in the right hand, state where and when you are, and say what this pooja is for. Discard the akshatai to the north afterwards and rinse the hand.', 'Put a few grains of akshatai in your left palm and rest it, palm up, on your right thigh. Cover it with your right palm, crossed over the left, and keep both hands there while you state where and when you are and say what this pooja is for. Afterwards, discard the akshatai to the north and wash your hands.'), updated_at = now()
 where pooja_id = 'nitya_panchayatana' and step_number = 5 and step_title_en = 'Sankalpam' and position('Hold akshatai in the right hand, state where and when you are, and say what this pooja is for. Discard the akshatai to the north afterwards and rinse the hand.' in instruction_en) > 0 and position('Put a few grains of akshatai in your left palm and rest it, palm up, on your right thigh. Cover it with your right palm, crossed over the left, and keep both hands there while you state where and when you are and say what this pooja is for. Afterwards, discard the akshatai to the north and wash your hands.' in instruction_en) = 0;

-- nitya_panchayatana #5.instruction_ta
update public.pooja_steps set instruction_ta = replace(instruction_ta, 'வலது கையில் அக்ஷதையை வைத்துக்கொண்டு, இடம் காலம் கூறி, இந்தப் பூஜை எதற்காக என்பதைச் சொல்லவும். பின் அக்ஷதையை வடக்கே விட்டு கையைக் கழுவவும்.', 'இடது உள்ளங்கையில் சிறிது அக்ஷதை வைத்து, அதை மேல்நோக்கியபடி வலது தொடையின் மேல் வைக்கவும். வலது உள்ளங்கையை அதன் மேல் குறுக்காக வைத்து மூடி, அப்படியே வைத்தபடி இடம் காலம் கூறி, இந்தப் பூஜை எதற்காக என்பதைச் சொல்லவும். பின் அக்ஷதையை வடக்கே விட்டுக் கைகளைக் கழுவவும்.'), updated_at = now()
 where pooja_id = 'nitya_panchayatana' and step_number = 5 and step_title_en = 'Sankalpam' and position('வலது கையில் அக்ஷதையை வைத்துக்கொண்டு, இடம் காலம் கூறி, இந்தப் பூஜை எதற்காக என்பதைச் சொல்லவும். பின் அக்ஷதையை வடக்கே விட்டு கையைக் கழுவவும்.' in instruction_ta) > 0 and position('இடது உள்ளங்கையில் சிறிது அக்ஷதை வைத்து, அதை மேல்நோக்கியபடி வலது தொடையின் மேல் வைக்கவும். வலது உள்ளங்கையை அதன் மேல் குறுக்காக வைத்து மூடி, அப்படியே வைத்தபடி இடம் காலம் கூறி, இந்தப் பூஜை எதற்காக என்பதைச் சொல்லவும். பின் அக்ஷதையை வடக்கே விட்டுக் கைகளைக் கழுவவும்.' in instruction_ta) = 0;

