-- varalakshmi_vratham #24.instruction_ta
update public.pooja_steps set instruction_ta = replace(instruction_ta, 'நடக்க இடமில்லையென்றால், அமர்ந்த இடத்திலேயே சுற்றித் திரும்பவும்.', 'நடக்க இடமில்லையென்றால், எழுந்து நின்று, நின்ற இடத்திலேயே மூன்று முறை வலமாகச் சுற்றவும்.'), updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_number = 24 and step_title_en = 'Pradakshina' and position('நடக்க இடமில்லையென்றால், அமர்ந்த இடத்திலேயே சுற்றித் திரும்பவும்.' in instruction_ta) > 0 and position('நடக்க இடமில்லையென்றால், எழுந்து நின்று, நின்ற இடத்திலேயே மூன்று முறை வலமாகச் சுற்றவும்.' in instruction_ta) = 0;

-- saraswati_pooja #22.instruction_en
update public.pooja_steps set instruction_en = replace(instruction_en, 'Then go round clockwise with palms joined, or turn in place.', 'Then go round clockwise three times with palms joined, or stand and turn clockwise three times where you are.'), updated_at = now()
 where pooja_id = 'saraswati_pooja' and step_number = 22 and step_title_en = 'Mantra Pushpam & Pradakshina' and position('Then go round clockwise with palms joined, or turn in place.' in instruction_en) > 0 and position('Then go round clockwise three times with palms joined, or stand and turn clockwise three times where you are.' in instruction_en) = 0;

-- saraswati_pooja #22.instruction_ta
update public.pooja_steps set instruction_ta = replace(instruction_ta, 'பின் கைகூப்பி வலமாகச் சுற்றவும், அல்லது நின்ற இடத்தில் சுற்றவும்.', 'பின் கைகூப்பி மூன்று முறை வலம் வரவும், அல்லது நின்ற இடத்திலேயே மூன்று முறை வலமாகச் சுற்றவும்.'), updated_at = now()
 where pooja_id = 'saraswati_pooja' and step_number = 22 and step_title_en = 'Mantra Pushpam & Pradakshina' and position('பின் கைகூப்பி வலமாகச் சுற்றவும், அல்லது நின்ற இடத்தில் சுற்றவும்.' in instruction_ta) > 0 and position('பின் கைகூப்பி மூன்று முறை வலம் வரவும், அல்லது நின்ற இடத்திலேயே மூன்று முறை வலமாகச் சுற்றவும்.' in instruction_ta) = 0;

-- nitya_panchayatana #33.instruction_en
update public.pooja_steps set instruction_en = replace(instruction_en, 'Circle the deities with palms together, or turn in place, and prostrate.', 'Circle the deities three times with palms together, or stand and turn clockwise three times where you are, and prostrate.'), updated_at = now()
 where pooja_id = 'nitya_panchayatana' and step_number = 33 and step_title_en = 'Pradakshina Namaskaram' and position('Circle the deities with palms together, or turn in place, and prostrate.' in instruction_en) > 0 and position('Circle the deities three times with palms together, or stand and turn clockwise three times where you are, and prostrate.' in instruction_en) = 0;

-- nitya_panchayatana #33.instruction_ta
update public.pooja_steps set instruction_ta = replace(instruction_ta, 'கைகூப்பி தெய்வங்களை வலம் வரவும், அல்லது நின்ற இடத்திலேயே சுற்றவும்.', 'கைகூப்பி தெய்வங்களை மூன்று முறை வலம் வரவும், அல்லது நின்ற இடத்திலேயே மூன்று முறை வலமாகச் சுற்றவும்.'), updated_at = now()
 where pooja_id = 'nitya_panchayatana' and step_number = 33 and step_title_en = 'Pradakshina Namaskaram' and position('கைகூப்பி தெய்வங்களை வலம் வரவும், அல்லது நின்ற இடத்திலேயே சுற்றவும்.' in instruction_ta) > 0 and position('கைகூப்பி தெய்வங்களை மூன்று முறை வலம் வரவும், அல்லது நின்ற இடத்திலேயே மூன்று முறை வலமாகச் சுற்றவும்.' in instruction_ta) = 0;

-- ganesha_standard #21.instruction_en
update public.pooja_steps set instruction_en = replace(instruction_en, 'For the kara nyasa roll the thumb from the base of each finger to its tip in turn, then rub the palms together.', 'For the kara nyasa roll the index finger from the base of the thumb to its tip, then roll the thumb from the base of the index, middle, ring and little fingers to their tips in turn, then rub the palms together.'), updated_at = now()
 where pooja_id = 'ganesha_standard' and step_number = 21 and step_title_en = 'Prana Pratishtha' and position('For the kara nyasa roll the thumb from the base of each finger to its tip in turn, then rub the palms together.' in instruction_en) > 0 and position('For the kara nyasa roll the index finger from the base of the thumb to its tip, then roll the thumb from the base of the index, middle, ring and little fingers to their tips in turn, then rub the palms together.' in instruction_en) = 0;

-- ganesha_standard #21.instruction_ta
update public.pooja_steps set instruction_ta = replace(instruction_ta, 'கர ந்யாஸத்தில், ஒவ்வொரு விரலின் அடியிலிருந்து நுனி வரை கட்டைவிரலை உருட்டவும்;', 'கர ந்யாஸத்தில், கட்டைவிரலின் அடியிலிருந்து நுனி வரை ஆள்காட்டி விரலை உருட்டவும்; பின் ஆள்காட்டி, நடு, மோதிர, சுண்டு விரல்கள் ஒவ்வொன்றின் அடியிலிருந்து நுனி வரை கட்டைவிரலை உருட்டவும்;'), updated_at = now()
 where pooja_id = 'ganesha_standard' and step_number = 21 and step_title_en = 'Prana Pratishtha' and position('கர ந்யாஸத்தில், ஒவ்வொரு விரலின் அடியிலிருந்து நுனி வரை கட்டைவிரலை உருட்டவும்;' in instruction_ta) > 0 and position('கர ந்யாஸத்தில், கட்டைவிரலின் அடியிலிருந்து நுனி வரை ஆள்காட்டி விரலை உருட்டவும்; பின் ஆள்காட்டி, நடு, மோதிர, சுண்டு விரல்கள் ஒவ்வொன்றின் அடியிலிருந்து நுனி வரை கட்டைவிரலை உருட்டவும்;' in instruction_ta) = 0;

do $$
declare n int;
begin
  select count(*) into n from public.pooja_steps where pooja_id = 'ganesha_standard' and step_number = 1 and step_title_en = 'Achamanam' and position('Sit facing East. Take a spoonful of water (Uddharani) from the Panchapatra in your right palm and sip it after chanting each name.' in instruction_en) > 0;
