  select count(*) into n from public.pooja_steps where pooja_id = 'ganesha_standard' and step_number = 1 and step_title_en = 'Achamanam' and position('கிழக்கு நோக்கி அமரவும். பஞ்சபாத்திரத்திலிருந்து உத்தரிணியால் சிறிது நீரை வலது உள்ளங்கையில் எடுத்து, ஒவ்வொரு நாமத்தையும் சொல்லிய பின் அருந்தவும்.' in instruction_ta) > 0;
  if n <> 0 then raise exception 'ganesha_standard #1.instruction_ta: the old clause survived'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'ganesha_standard' and step_number = 1 and step_title_en = 'Achamanam' and position('கிழக்கு அல்லது வடக்கு நோக்கி அமரவும். வலது கையின் ஆள்காட்டி விரலைக் கட்டைவிரலுடன் சேர்த்து மடக்கி, மற்ற மூன்று விரல்களையும் குவித்து, பஞ்சபாத்திரத்திலிருந்து உத்தரிணியால் எடுத்த ஒரு உத்தரிணி நீர் உள்ளங்கையில் நிற்கும்படி வைக்கவும். மூன்று நாமங்களில் ஒவ்வொன்றுக்கும் ஒரு முறை அந்த நீரை அருந்தவும்.' in instruction_ta) > 0;
